//! The math symbol table: which symbol a glyph of a math font is.
//!
//! A glyph says `CMMI10` and character code 11; a reader of mathematics needs "α, a Greek letter,
//! LaTeX `\alpha`". The table (`symbols/table.tsv`) is generated by `cargo xtask math-symbols
//! generate`, which typesets a hand-written list of LaTeX commands (`symbols/commands.txt`) with
//! TeX and reads the font and code TeX used from the DVI, so the codes are TeX's own and nothing
//! here is copied from a package or font map. Reading the table needs no TeX.
//!
//! Keys are by font *family* (`cmmi`, not `cmmi7`): the size comes from the glyph. A font or code the
//! table does not know is reported ([`Lookup::UnknownFont`], [`Lookup::UnknownCode`]), never guessed.
//!
//! Some things TeX draws with several glyphs (`\ne` is a slash over `=`, `\sin` is three letters,
//! `\longrightarrow` a bar and an arrow): those are [`Compound`]s, matched by what their parts are and
//! where they stand relative to the first.

use std::collections::HashMap;
use std::sync::OnceLock;

/// The generated table, included at build time.
const TABLE: &str = include_str!("symbols/table.tsv");

/// TeX's math class of a symbol, which decides its spacing.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Class {
    Ord,
    /// An operator name such as `\sin`.
    Op,
    Bin,
    Rel,
    Open,
    Close,
    Punct,
    /// A large operator (`\sum`, `\int`).
    Large,
    Inner,
}

/// What a glyph is when it is a letter or digit.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Kind {
    Sym,
    Latin,
    Greek,
    Digit,
}

/// The alphabet a letter is drawn in.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Alphabet {
    /// Math italic: what a plain letter is in a formula.
    Math,
    /// `\mathrm`.
    Roman,
    /// `\mathit` (text italic).
    Italic,
    /// `\mathbf`.
    Bold,
    /// `\mathbb`.
    Blackboard,
    /// `\mathfrak`.
    Fraktur,
    /// `\mathcal`.
    Calligraphic,
    /// `unicode-math`'s `\symbf`: the bold letters of the math font (U+1D400…).
    SymBold,
    /// `\symbfit` (U+1D468…).
    SymBoldItalic,
    /// `\symsf` (U+1D5A0…).
    SymSans,
    /// `\symtt` (U+1D670…).
    SymMono,
}

impl Alphabet {
    /// The command that selects it; `None` for math italic, which needs none.
    pub fn command(self) -> Option<&'static str> {
        match self {
            Alphabet::Math => None,
            Alphabet::Roman => Some("\\mathrm"),
            Alphabet::Italic => Some("\\mathit"),
            Alphabet::Bold => Some("\\mathbf"),
            Alphabet::Blackboard => Some("\\mathbb"),
            Alphabet::Fraktur => Some("\\mathfrak"),
            Alphabet::Calligraphic => Some("\\mathcal"),
            Alphabet::SymBold => Some("\\symbf"),
            Alphabet::SymBoldItalic => Some("\\symbfit"),
            Alphabet::SymSans => Some("\\symsf"),
            Alphabet::SymMono => Some("\\symtt"),
        }
    }
}

/// A piece of an extensible symbol, in the order it is stacked (or set side by side).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Role {
    Top,
    Mid,
    Bot,
    Rep,
    Left,
    Right,
}

/// What a glyph is, as the table knows it.
#[derive(Clone, Debug, PartialEq)]
pub struct Symbol {
    /// The LaTeX that sets it: `\alpha`, `+`, `\mathbb{R}`.
    pub latex: String,
    /// Unicode text of the symbol; empty when it has none.
    pub unicode: String,
    pub class: Class,
    pub kind: Kind,
    pub alphabet: Option<Alphabet>,
    /// Sizes the glyph is a member of: the family (`(`, `\sum`, `\sqrt`) and its rank, 0 the smallest.
    pub variants: Vec<(String, u8)>,
    /// Extensible pieces the glyph is: the family and the role.
    pub pieces: Vec<(String, Role)>,
    /// The `\big…` command size (1 `\big`, 2 `\Big`, 3 `\bigg`, 4 `\Bigg`) that selects this glyph.
    pub big: Option<u8>,
    pub accent: bool,
    /// The glyph's advance width, italic correction, height and depth, in thousandths of an em.
    pub width: i16,
    pub italic: i16,
    pub height: i16,
    pub depth: i16,
    /// Read from a glyph's Unicode text ([`super::unicode`]), not from the table: no metrics, and a
    /// size known only from the glyph's ink.
    pub from_unicode: bool,
}

/// One glyph of a [`Compound`].
#[derive(Clone, Debug, PartialEq)]
pub struct Part {
    pub family: u16,
    pub code: u32,
    /// Where its origin is relative to the first part's, in ems of the first part's size.
    pub dx: f32,
    pub dy: f32,
    /// Its size relative to the first part's.
    pub scale: f32,
}

/// Something TeX draws with several glyphs.
#[derive(Clone, Debug, PartialEq)]
pub struct Compound {
    pub latex: String,
    pub unicode: String,
    pub class: Class,
    /// A function name (`\sin`).
    pub function: bool,
    /// Where the row's baseline lies below the first part's origin, in ems of the first part's size.
    pub base: f32,
    pub parts: Vec<Part>,
}

/// The result of asking the table about a glyph.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Lookup<'a> {
    Known(&'a Symbol),
    /// The font is not one the table covers (a text font, an OpenType math font, …).
    UnknownFont,
    /// The font is covered but has no symbol with this code.
    UnknownCode,
}

/// The table, parsed.
#[derive(Debug, Default)]
pub struct SymbolTable {
    families: HashMap<String, u16>,
    singles: HashMap<(u16, u32), Symbol>,
    /// Compounds by their first part.
    compounds: HashMap<(u16, u32), Vec<Compound>>,
    /// Lines of the table that could not be read; a generated table has none.
    pub malformed: usize,
}

/// The family of a font name: the base font without its subset prefix, lower case, and without the
/// design size (`ABCDEF+CMMI10` and `cmmi7` are both `cmmi`). `None` for a name with nothing left.
pub fn family_of(font_name: &str) -> Option<String> {
    let name = match font_name.split_once('+') {
        Some((prefix, rest)) if prefix.len() == 6 && prefix.bytes().all(|b| b.is_ascii_uppercase()) => rest,
        _ => font_name,
    };
    let family = name.to_ascii_lowercase();
    let family = family.trim_end_matches(|c: char| c.is_ascii_digit());
    (!family.is_empty()).then(|| family.to_owned())
}

fn class_of(s: &str) -> Option<Class> {
    Some(match s {
        "ord" => Class::Ord,
        "op" => Class::Op,
        "bin" => Class::Bin,
        "rel" => Class::Rel,
        "open" => Class::Open,
        "close" => Class::Close,
        "punct" => Class::Punct,
        "large" => Class::Large,
        "inner" => Class::Inner,
        _ => return None,
    })
}

fn kind_of(s: &str) -> Option<Kind> {
    Some(match s {
        "sym" => Kind::Sym,
        "latin" => Kind::Latin,
        "greek" => Kind::Greek,
        "digit" => Kind::Digit,
        _ => return None,
    })
}

fn alphabet_of(s: &str) -> Option<Alphabet> {
    Some(match s {
        "math" => Alphabet::Math,
        "rm" => Alphabet::Roman,
        "it" => Alphabet::Italic,
        "bf" => Alphabet::Bold,
        "bb" => Alphabet::Blackboard,
        "frak" => Alphabet::Fraktur,
        "cal" => Alphabet::Calligraphic,
        _ => return None,
    })
}

fn role_of(s: &str) -> Option<Role> {
    Some(match s {
        "top" => Role::Top,
        "mid" => Role::Mid,
        "bot" => Role::Bot,
        "rep" => Role::Rep,
        "left" => Role::Left,
        "right" => Role::Right,
        _ => return None,
    })
}

/// Unicode text from `1D7CE` or `0041+0302`; empty for `-`.
fn unicode_of(s: &str) -> Option<String> {
    if s == "-" {
        return Some(String::new());
    }
    s.split('+').map(|h| u32::from_str_radix(h, 16).ok().and_then(char::from_u32)).collect()
}

struct Flags {
    variants: Vec<(String, u8)>,
    pieces: Vec<(String, Role)>,
    big: Option<u8>,
    alphabet: Option<Alphabet>,
    accent: bool,
    function: bool,
}

fn flags_of(s: &str) -> Option<Flags> {
    let mut f = Flags { variants: Vec::new(), pieces: Vec::new(), big: None, alphabet: None, accent: false, function: false };
    if s == "-" {
        return Some(f);
    }
    for flag in s.split(',') {
        if let Some(v) = flag.strip_prefix("var=") {
            let (group, rank) = v.rsplit_once(':')?;
            f.variants.push((group.to_owned(), rank.parse().ok()?));
        } else if let Some(v) = flag.strip_prefix("ext=") {
            let (group, role) = v.rsplit_once(':')?;
            f.pieces.push((group.to_owned(), role_of(role)?));
        } else if let Some(v) = flag.strip_prefix("big=") {
            f.big = Some(v.parse().ok()?);
        } else if let Some(v) = flag.strip_prefix("alpha=") {
            f.alphabet = Some(alphabet_of(v)?);
        } else if flag == "acc" {
            f.accent = true;
        } else if flag == "fn" {
            f.function = true;
        } else {
            return None;
        }
    }
    Some(f)
}

impl SymbolTable {
    /// Parses a table in the format `cargo xtask math-symbols generate` writes. Lines that do not
    /// parse are counted in [`malformed`](Self::malformed) and skipped.
    pub fn parse(text: &str) -> SymbolTable {
        let mut t = SymbolTable::default();
        for line in text.lines() {
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            if t.parse_line(line).is_none() {
                t.malformed += 1;
            }
        }
        t
    }

    fn family_id(&mut self, family: &str) -> u16 {
        let next = u16::try_from(self.families.len()).unwrap_or(u16::MAX);
        *self.families.entry(family.to_owned()).or_insert(next)
    }

    fn parse_line(&mut self, line: &str) -> Option<()> {
        let f: Vec<&str> = line.split('\t').collect();
        match *f.first()? {
            "S" => {
                let [_, family, code, latex, unicode, class, kind, flags, width, italic, height, depth, ..] = f[..] else { return None };
                let flags = flags_of(flags)?;
                let id = self.family_id(family);
                let metric = |s: &str| s.parse::<i16>().ok();
                let symbol = Symbol {
                    latex: latex.to_owned(),
                    unicode: unicode_of(unicode)?,
                    class: class_of(class)?,
                    kind: kind_of(kind)?,
                    alphabet: flags.alphabet,
                    variants: flags.variants,
                    pieces: flags.pieces,
                    big: flags.big,
                    accent: flags.accent,
                    width: metric(width)?,
                    italic: metric(italic)?,
                    height: metric(height)?,
                    depth: metric(depth)?,
                    from_unicode: false,
                };
                self.singles.insert((id, code.parse().ok()?), symbol);
            }
            "C" => {
                let [_, latex, unicode, class, _kind, flags, _env, _tex, base, parts] = f[..] else { return None };
                let flags = flags_of(flags)?;
                let mut out = Vec::new();
                for p in parts.split(';') {
                    let a: Vec<&str> = p.split(':').collect();
                    let [family, code, dx, dy, size] = a[..] else { return None };
                    let per_mille = |s: &str| s.parse::<f32>().ok().map(|v| v / 1000.0);
                    out.push(Part {
                        family: self.family_id(family),
                        code: code.parse().ok()?,
                        dx: per_mille(dx)?,
                        dy: per_mille(dy)?,
                        scale: per_mille(size)?,
                    });
                }
                let first = out.first()?;
                let key = (first.family, first.code);
                let compound = Compound {
                    latex: latex.to_owned(),
                    unicode: unicode_of(unicode)?,
                    class: class_of(class)?,
                    function: flags.function,
                    base: base.parse::<f32>().ok()? / 1000.0,
                    parts: out,
                };
                self.compounds.entry(key).or_default().push(compound);
            }
            _ => return None,
        }
        Some(())
    }

    /// The id of a font family the table covers.
    pub fn family(&self, family: &str) -> Option<u16> {
        self.families.get(family).copied()
    }

    /// The symbol drawn by `code` of the font `font_name` (a base font name, subset prefix allowed).
    pub fn lookup(&self, font_name: &str, code: u32) -> Lookup<'_> {
        let Some(id) = family_of(font_name).and_then(|f| self.family(&f)) else { return Lookup::UnknownFont };
        self.lookup_id(id, code)
    }

    /// As [`lookup`](Self::lookup) for a family id from [`family`](Self::family).
    pub fn lookup_id(&self, family: u16, code: u32) -> Lookup<'_> {
        match self.singles.get(&(family, code)) {
            Some(s) => Lookup::Known(s),
            None => Lookup::UnknownCode,
        }
    }

    /// The compounds whose first glyph is `code` of `family`; longest first.
    pub fn compounds_from(&self, family: u16, code: u32) -> &[Compound] {
        self.compounds.get(&(family, code)).map_or(&[], Vec::as_slice)
    }

    /// Every single-glyph symbol: family name, code, symbol (for tests and tools).
    pub fn symbols(&self) -> impl Iterator<Item = (&str, u32, &Symbol)> {
        self.singles.iter().filter_map(|((f, code), s)| {
            let name = self.families.iter().find(|(_, id)| *id == f).map(|(n, _)| n.as_str())?;
            Some((name, *code, s))
        })
    }

    /// Every compound.
    pub fn all_compounds(&self) -> impl Iterator<Item = &Compound> {
        self.compounds.values().flatten()
    }

    /// The sizes of a delimiter family, smallest first: rank, and height plus depth in thousandths
    /// of an em.
    pub fn ladder(&self, group: &str) -> Vec<(u8, i16)> {
        let mut v: Vec<(u8, i16)> = self
            .singles
            .values()
            .flat_map(|s| s.variants.iter().filter(|(g, _)| g == group).map(move |(_, r)| (*r, s.height.saturating_add(s.depth))))
            .collect();
        v.sort_unstable();
        v.dedup_by_key(|x| x.0);
        v
    }

    /// The name of a family id.
    pub fn family_name(&self, id: u16) -> Option<&str> {
        self.families.iter().find(|(_, v)| **v == id).map(|(n, _)| n.as_str())
    }
}

/// The built-in table (parsed once).
pub fn table() -> &'static SymbolTable {
    static TABLE_ONCE: OnceLock<SymbolTable> = OnceLock::new();
    TABLE_ONCE.get_or_init(|| {
        let mut t = SymbolTable::parse(TABLE);
        for list in t.compounds.values_mut() {
            list.sort_by(|a, b| b.parts.len().cmp(&a.parts.len()).then_with(|| a.latex.cmp(&b.latex)));
        }
        t
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_built_in_table_parses_cleanly() {
        let t = table();
        assert_eq!(t.malformed, 0);
        assert!(t.symbols().count() > 800, "{}", t.symbols().count());
        assert!(t.all_compounds().count() > 50);
    }

    #[test]
    fn alpha_is_cmmi_11() {
        let Lookup::Known(s) = table().lookup("ABCDEF+CMMI10", 11) else { panic!("cmmi 11") };
        assert_eq!(s.latex, "\\alpha");
        assert_eq!(s.unicode, "\u{3b1}");
        assert_eq!(s.kind, Kind::Greek);
        assert_eq!(s.class, Class::Ord);
        // The family, not the design size, picks the table; case does not matter.
        assert!(matches!(table().lookup("cmmi5", 11), Lookup::Known(_)));
        assert!(matches!(table().lookup("CMMI7", 11), Lookup::Known(_)));
    }

    #[test]
    fn unknown_fonts_and_codes_are_reported() {
        assert_eq!(table().lookup("Times-Roman", 65), Lookup::UnknownFont);
        assert_eq!(table().lookup("", 65), Lookup::UnknownFont);
        assert_eq!(table().lookup("ABCDEF+", 65), Lookup::UnknownFont);
        assert_eq!(table().lookup("CMMI10", 0x7fff_ffff), Lookup::UnknownCode);
    }

    #[test]
    fn family_names_lose_prefix_case_and_size() {
        assert_eq!(family_of("ABCDEF+CMSY10").as_deref(), Some("cmsy"));
        assert_eq!(family_of("msbm10").as_deref(), Some("msbm"));
        // Not a subset prefix: kept.
        assert_eq!(family_of("ABC+CMR10").as_deref(), Some("abc+cmr"));
        assert_eq!(family_of("12"), None);
    }

    #[test]
    fn variants_and_pieces_are_recorded() {
        let t = table();
        let Some(mem) = t.family("cmex") else { panic!("cmex is in the table") };
        // `\sum`: text size and display size are ranks 0 and 1 of one family.
        let sums: Vec<_> =
            (0..128).filter_map(|c| if let Lookup::Known(s) = t.lookup_id(mem, c) { Some(s) } else { None }).filter(|s| s.latex == "\\sum").collect();
        assert_eq!(sums.len(), 2);
        assert!(sums.iter().any(|s| s.variants.contains(&("\\sum".to_owned(), 0))));
        assert!(sums.iter().any(|s| s.variants.contains(&("\\sum".to_owned(), 1))));
        // A tall parenthesis has top, bottom and repeated pieces.
        let roles: Vec<Role> = (0..128)
            .filter_map(|c| if let Lookup::Known(s) = t.lookup_id(mem, c) { Some(s) } else { None })
            .flat_map(|s| s.pieces.iter().filter(|(g, _)| g == "(").map(|(_, r)| *r).collect::<Vec<_>>())
            .collect();
        assert!(roles.contains(&Role::Top) && roles.contains(&Role::Bot) && roles.contains(&Role::Rep), "{roles:?}");
    }

    #[test]
    fn compounds_are_found_by_their_first_glyph() {
        let t = table();
        // `\ne` is a slash (CMSY 54) over an equals sign.
        let Some(cmsy) = t.family("cmsy") else { panic!("cmsy") };
        let ne: Vec<_> = t.compounds_from(cmsy, 54).iter().map(|c| c.latex.as_str()).collect();
        assert!(ne.contains(&"\\ne"), "{ne:?}");
        assert!(t.all_compounds().any(|c| c.latex == "\\notin" && c.parts.len() == 2));
    }

    #[test]
    fn a_damaged_table_loses_lines_not_the_program() {
        let t = SymbolTable::parse(
            "S\tcmmi\t11\t\\alpha\t03B1\tord\tgreek\t-\t1\t2\t3\t4\ti\t\\alpha\nS\tbroken\nX\tunknown\nC\t\\a\t41\tord\tsym\t-\ti\t\\a\t0\tcmr:1:x\n",
        );
        assert_eq!(t.malformed, 3);
        assert!(matches!(t.lookup("cmmi10", 11), Lookup::Known(_)));
    }
}
